-- German (deDE): the guide forever/class/hunter/rhokdelar (forever/class/hunter/rhokdelar.guide).
-- Written by `forge i18n guides sync deDE`, which keeps every translation (docs/TRANSLATING.md, "Guide texts").
-- Translate the right-hand sides; "" shows the English. Keep each {kind:id} as it is: the game shows its
-- name there in German (the English is listed above the line). A name the English has in the plural, as words,
-- may be written with the singular's token from its "plural, as words" line: "Bandidos ({npc:251918})", "{npc:251918} ×8".
-- A token marked "no name in this language" would show in English: write that name in German words instead.
-- The comments are rewritten by sync.
return {
	-- Guide
	["Rhok'delar and Lok'delar"] = "Rhok'delar und Lok'delar",
	["The hunter's epic bow chain: in Classic the stave and sinew became Rhok'delar and Lok'delar (unconfirmed in Forever)."] = "Die epische Bogen-Questreihe der Jäger: In Classic wurden aus Stab und Sehne Rhok'delar und Lok'delar (in Forever unbestätigt).",

	-- Step 1: The Ancient Petrified Leaf
	-- {item:18703} Ancient Petrified Leaf
	["The {item:18703}"] = "{item:18703}",
	-- {area:2717} Molten Core · {area:254} Blackrock Mountain · {npc:12018} Majordomo Executus · {object:179703} Cache of the Firelord · {item:18703} Ancient Petrified Leaf
	["{area:2717} is a 40-player raid inside {area:254}. When {npc:12018} yields, the {object:179703} appears; it holds the {item:18703} about half the time, one per kill, so it may take several weeks of raids. Right-click the leaf to start the quest."] = "{area:2717} ist ein Schlachtzug für 40 Spieler in {area:254}. Wenn {npc:12018} nachgibt, erscheint {object:179703}; sie enthält {item:18703} etwa in der Hälfte der Fälle, eines pro Kill, es kann also mehrere Wochen Schlachtzüge dauern. Klicke das Blatt mit der rechten Maustaste an, um die Quest zu starten.",
	-- {item:18703} Ancient Petrified Leaf
	["from the {item:18703}"] = "von {item:18703}",

	-- Step 2: Vartrus the Ancient
	-- {npc:14526} Hastat the Ancient · {area:1767} Irontree Woods · {zone:1448} Felwood · {area:1998} Talonbranch Glade · {area:1997} Bloodvenom Post · {quest:7636} Stave of the Ancients
	["Vartrus, Stoma and {npc:14526} are petrified trees on a small island in a ring-shaped lake in {area:1767}, north {zone:1448}. Their spirits only appear when someone carrying the leaf climbs the island's little hill to its east edge. Alliance: fly to {area:1998}; Horde: fly to {area:1997}. Vartrus gives {quest:7636}, Stoma A Proper String, Hastat the quiver; each can be handed in on its own."] = "Vartrus, Stoma und {npc:14526} sind versteinerte Bäume auf einer kleinen Insel in einem ringförmigen See in {area:1767}, nördlich von {zone:1448}. Ihre Geister erscheinen nur, wenn jemand mit dem Blatt den kleinen Hügel der Insel bis zu seinem Ostrand hinaufsteigt. Allianz: Flieg nach {area:1998}; Horde: Flieg nach {area:1997}. Vartrus gibt {quest:7636}, Stoma A Proper String, Hastat den Köcher; jede kann einzeln abgegeben werden.",
	-- {npc:14526} Hastat the Ancient
	["{npc:14526}: the quiver, last in this guide"] = "{npc:14526}: der Köcher, zuletzt in diesem Guide",

	-- Step 3: Before the demons
	["Before the demons"] = "Vor den Dämonen",
	-- {item:9224} Potion of Demon Slaying · {skill:171} Alchemy · {spell:19878} Track Demons
	-- plural, as words: Major Mana Potions = {item:13444} Major Mana Potion
	["The four demons are level 60 elites disguised as friendly travellers; talk to one and say you know what it is, and it turns into its demon form. Fight every one alone: no pet (dismiss it), no other player's heal, buff or attack once the fight starts, or the demon calls you a coward and vanishes, with a 3 hour wait for it to return (also after it dies). Buffs and potions you take before the pull are fine, and a friend may stand by to kill wandering monsters or enemy players, as long as they never touch the demon or you. Bring a {item:9224} ({skill:171} or the auction house), Major Mana Potions for the long kites, and a melee weapon with the Demonslaying enchant if you can. {spell:19878}, from your trainer, shows the disguised demons on the minimap. In a group, set loot to free for all so you can loot the head."] = "Die vier Dämonen sind Elite der Stufe 60, als freundliche Reisende getarnt; sprich einen an und sag, dass du weißt, was er ist, dann verwandelt er sich in seine Dämonengestalt. Kämpfe jeden allein: kein Begleiter (entlasse ihn), keine Heilung, kein Buff und kein Angriff eines anderen Spielers, sobald der Kampf beginnt, sonst nennt dich der Dämon einen Feigling und verschwindet, und es dauert 3 Stunden, bis er zurückkehrt (auch nach seinem Tod). Buffs und Tränke, die du vor dem Pull nimmst, sind in Ordnung, und ein Freund darf danebenstehen, um umherstreifende Monster oder gegnerische Spieler zu töten, solange er nie den Dämon oder dich berührt. Bring {item:9224} mit ({skill:171} oder das Auktionshaus), Große Manatränke für die langen Kites und eine Nahkampfwaffe mit der Verzauberung „Dämonentöten“, wenn du kannst. {spell:19878}, von deinem Lehrer, zeigt die getarnten Dämonen auf der Minikarte an. Stell in einer Gruppe die Beuteverteilung auf „Jeder gegen jeden“, damit du den Kopf plündern kannst.",
	-- {spell:19878} Track Demons
	["Learn {spell:19878} and get demon-slaying potions"] = "Lerne {spell:19878} und besorge Dämonentöten-Tränke",

	-- Step 4: Simone the Inconspicuous
	-- {npc:14527} Simone the Inconspicuous · {spell:19878} Track Demons · {npc:14533} Simone the Seductress · {spell:421} Chain Lightning · {spell:3034} Viper Sting · {spell:23205} Temptress' Kiss
	["{npc:14527}, a troll with a wolf, walks a long path that starts at the lake in western Un'Goro and can reach the south of the crater; use {spell:19878}. Talk to her and she becomes {npc:14533}, and her wolf Precious a Felstalker. The hardest of the four: Freezing Trap Precious and pull Simone well away from it, or kite Precious away and kill it first, let Simone reset and come back for her alone. Her {spell:421} hits hard, so drain her mana with {spell:3034} (a 15-second cooldown on Forever) and keep her busy; her {spell:23205} cuts your ranged attack power, so finish her in melee. Loot her head before Precious breaks free."] = "{npc:14527}, eine Trollin mit einem Wolf, geht einen langen Weg, der am See im Westen von Un'Goro beginnt und bis in den Süden des Kraters reichen kann; nutze {spell:19878}. Sprich sie an, und sie wird zu {npc:14533}, ihr Wolf Precious zu einem Teufelspirscher. Die schwerste der vier: Leg Precious eine Eiskältefalle und zieh Simone weit von ihm weg, oder kite Precious weg und töte ihn zuerst, lass Simone zurücksetzen und komm allein für sie zurück. Ihr {spell:421} trifft hart, also entzieh ihr mit {spell:3034} (auf Forever 15 Sekunden Cooldown) das Mana und halte sie beschäftigt; ihr {spell:23205} senkt deine Fernkampf-Angriffskraft, also erledige sie im Nahkampf. Plündere ihren Kopf, bevor Precious sich befreit.",

	-- Step 5: Franklin the Friendly
	-- {npc:14529} Franklin the Friendly · {zone:1428} Burning Steppes · {area:254} Blackrock Mountain · {npc:14534} Klinfran the Crazed · {spell:3043} Scorpid Sting · {spell:23257} Demonic Frenzy · {spell:19801} Tranquilizing Shot · {spell:2974} Wing Clip · {spell:2973} Raptor Strike
	["{npc:14529}, a human, wanders the western {zone:1428} south of {area:254}. Talk to him and he becomes {npc:14534}, the easiest of the four. Keep {spell:3043} on him the whole fight: while it lasts he barely hurts you. When he goes into {spell:23257}, remove it with {spell:19801} and never stand in melee while it is up; between frenzies you can fight him in melee with {spell:2974} and {spell:2973}. He cannot leave the {zone:1428}, so kite him around the trees if needed."] = "{npc:14529}, ein Mensch, wandert durch den Westen von {zone:1428} südlich von {area:254}. Sprich ihn an, und er wird zu {npc:14534}, dem leichtesten der vier. Halte {spell:3043} den ganzen Kampf über auf ihm: Solange er wirkt, tut er dir kaum weh. Wenn er in {spell:23257} geht, entferne ihn mit {spell:19801} und steh nie im Nahkampf, solange er aktiv ist; zwischen den Raserei-Phasen kannst du ihn mit {spell:2974} und {spell:2973} im Nahkampf bekämpfen. Er kann {zone:1428} nicht verlassen, also kite ihn bei Bedarf um die Bäume.",

	-- Step 6: Nelson the Nice
	-- {npc:14536} Nelson the Nice · {area:3428} Ahn'Qiraj · {zone:1451} Silithus · {npc:14530} Solenor the Slayer · {spell:23272} Soul Flame · {object:164639} Frost Trap (no name in this language: may be words) · {spell:5384} Feign Death · {spell:2974} Wing Clip · {npc:14761} Creeping Doom · {spell:2643} Multi-Shot
	["{npc:14536}, a gnome, walks around the gates of {area:3428} in the far south-west of {zone:1451}. Talk to him and he becomes {npc:14530}. He enrages with {spell:23272} as he turns: drop a {object:164639}, {spell:5384}, and he resets without the enrage. {spell:2974} roots him for a long time; while rooted he fears you and sends beetles ({npc:14761}): kill them fast with traps and {spell:2643} before they wear you down."] = "{npc:14536}, ein Gnom, läuft um die Tore von {area:3428} im äußersten Südwesten von {zone:1451}. Sprich ihn an, und er wird zu {npc:14530}. Bei der Verwandlung wird er mit {spell:23272} wütend: Wirf eine {object:164639}, {spell:5384}, und er setzt ohne die Wut zurück. {spell:2974} wurzelt ihn lange fest; solange er festgewurzelt ist, versetzt er dich in Furcht und schickt Käfer ({npc:14761}): Töte sie schnell mit Fallen und {spell:2643}, bevor sie dich zermürben.",

	-- Step 7: Artorius the Amiable
	-- {npc:14531} Artorius the Amiable · {zone:1452} Winterspring · {area:2255} Everlook · {npc:14535} Artorius the Doombringer · {spell:23298} Demonic Doom · {spell:5118} Aspect of the Cheetah · {spell:1978} Serpent Sting · {spell:23299} Stinging Trauma · {spell:23257} Demonic Frenzy · {spell:19801} Tranquilizing Shot
	["{npc:14531}, a tauren, walks a loop in the rocks of northern {zone:1452}, north of {area:2255}. Talk to him and he becomes {npc:14535}. Within 30 yards of him {spell:23298} hits hard: keep your distance and kite him the whole fight, {spell:5118} on, south down the road. {spell:1978} on him adds {spell:23299}, extra Nature damage, so keep it ticking while you run; his {spell:23257} can be removed with {spell:19801}, but distance matters more. It is a long fight: bring mana potions and plan your kiting path."] = "{npc:14531}, ein Tauren, geht eine Runde in den Felsen im Norden von {zone:1452}, nördlich von {area:2255}. Sprich ihn an, und er wird zu {npc:14535}. Im Umkreis von 30 Metern um ihn trifft {spell:23298} hart: Halte Abstand und kite ihn den ganzen Kampf über, {spell:5118} an, die Straße nach Süden. {spell:1978} auf ihm fügt {spell:23299} hinzu, zusätzlichen Naturschaden, also halte ihn am Ticken, während du läufst; seine {spell:23257} lässt sich mit {spell:19801} entfernen, aber der Abstand ist wichtiger. Es ist ein langer Kampf: Bring Manatränke mit und plane deinen Kite-Weg.",

	-- Step 8: Onyxia
	["Onyxia"] = "Onyxia",
	-- {area:2159} Onyxia's Lair · {area:511} Wyrmbog · {zone:1445} Dustwallow Marsh · {item:18705} Mature Black Dragon Sinew
	["Onyxia is the 40-player raid boss of {area:2159}, a cave in the {area:511} of southern {zone:1445}; she returns once a week. She drops one {item:18705} in about two kills of five, lootable without the quest, so only one hunter per kill gets it: settle who first."] = "Onyxia ist der Schlachtzugsboss für 40 Spieler in {area:2159}, einer Höhle im {area:511} im Süden von {zone:1445}; sie kehrt einmal pro Woche zurück. Sie lässt in etwa zwei von fünf Kills {item:18705} fallen, plünderbar auch ohne die Quest, sodass nur ein Jäger pro Kill ihn bekommt: Klärt vorher, wer zuerst dran ist.",
	-- {item:18705} Mature Black Dragon Sinew
	["{item:18705}, from Onyxia"] = "{item:18705}, von Onyxia",

	-- Step 9: Back to the Ancients
	["Back to the Ancients"] = "Zurück zu den Uralten",

	-- Step 10: Rhok'delar and Lok'delar
	-- {item:18707} Ancient Rune Etched Stave · {item:18724} Enchanted Black Dragon Sinew · {item:18715} Lok'delar, Stave of the Ancient Keepers
	["Not confirmed in Forever. In Classic, using the {item:18707} with the {item:18724} in your bags made Rhok'delar, and talking to Vartrus once more then gave {item:18715}, at no extra cost."] = "In Forever nicht bestätigt. In Classic entstand Rhok'delar, wenn du {item:18707} mit {item:18724} in deinen Taschen benutzt hast, und ein weiteres Gespräch mit Vartrus gab dir dann {item:18715}, ohne Mehrkosten.",
	-- {item:18707} Ancient Rune Etched Stave
	["{item:18707}, by Vartrus"] = "{item:18707}, bei Vartrus dem Uralten",
	-- {npc:14524} Vartrus the Ancient
	["{npc:14524}: Lok'delar in Classic"] = "{npc:14524}: Lok'delar in Classic",

	-- Step 11: Azuregos
	-- {item:18704} Mature Blue Dragon Sinew · {npc:6109} Azuregos · {zone:1447} Azshara · {area:2245} Mazthoril · {area:2255} Everlook · {zone:1452} Winterspring
	["Hastat's quiver needs the {item:18704}. {npc:6109}, a world boss for a raid, stands in southern {zone:1447}, returns only every two to four days and drops it nearly every kill. The elite Cobalt dragonkin in and around {area:2245}, the cave south of {area:2255} in {zone:1452}, drop it about once in 200 kills; Manaclaw there a little more often. Skip the rest of this guide if you do not want the quiver."] = "Hastats Köcher braucht {item:18704}. {npc:6109}, ein Weltboss für einen Schlachtzug, steht im Süden von {zone:1447}, kehrt nur alle zwei bis vier Tage zurück und lässt ihn bei fast jedem Kill fallen. Die Cobalt-Drachkin-Elite in und um {area:2245}, die Höhle südlich von {area:2255} in {zone:1452}, lassen ihn etwa bei jedem 200. Kill fallen; Manaclaw dort etwas öfter. Überspring den Rest dieses Guides, wenn du den Köcher nicht willst.",
	-- {item:18704} Mature Blue Dragon Sinew · {npc:6109} Azuregos
	["{item:18704}, from {npc:6109}"] = "{item:18704}, von {npc:6109}",

	-- No longer in the guide (its English changed or it went away): reuse or delete.
	-- ["Azuregos"] = "Azuregos",
	-- ["Hastat's quiver needs the {item:18704}. {npc:6109}, a world boss for a raid, roams the south of {zone:1447} and drops it most of the time; the Cobalt dragonkin of {zone:1452} drop it very rarely. Skip the rest of this guide if you do not want the quiver."] = "Der Köcher von Hastat dem Uralten braucht {item:18704}. {npc:6109}, ein Weltboss für einen Schlachtzug, streift durch den Süden von {zone:1447} und lässt sie meistens fallen; die kobaltblauen Drachkin in {zone:1452} nur sehr selten. Überspringe den Rest dieses Guides, wenn du den Köcher nicht willst.",
	-- ["Not confirmed in Forever. In Classic, using the {item:18707} with the {item:18724} in your bags made Rhok'delar, and Vartrus then gave {item:18715} ({spell:425121})."] = "In Forever nicht bestätigt. In Classic ergab {item:18707} mit {item:18724} in den Taschen benutzt Rhok'delar, und Vartrus der Uralte gab dann {item:18715} ({spell:425121}).",
	-- ["Onyxia drops the {item:18705}; she is the 40-player raid boss of {area:2159}, a cave in the {area:511} of southern {zone:1445}."] = "Onyxia lässt {item:18705} fallen; sie ist der Schlachtzugsboss für 40 Spieler in {area:2159}, einer Höhle im {area:511} im Süden der {zone:1445}.",
	-- ["The {object:179703} appears in {area:2717} when {npc:12018} yields; it holds the {item:18703} about half the time. {area:2717} is a 40-player raid inside {area:254}. Right-click the leaf to start the quest."] = "{object:179703} erscheint im {area:2717}, wenn {npc:12018} aufgibt; in etwa jedem zweiten Fall enthält er {item:18703}. {area:2717} ist ein Schlachtzug für 40 Spieler im {area:254}. Rechtsklicke das Blatt, um die Quest zu starten.",
	-- ["Vartrus, Stoma and {npc:14526} stand together in the north of {zone:1448}. Alliance: {area:1998} is the nearest flight point; Horde: {area:1997}."] = "Vartrus der Uralte, Stoma der Uralte und {npc:14526} stehen zusammen im Norden von {zone:1448}. Allianz: {area:1998} ist der nächste Flugpunkt; Horde: {area:1997}.",
	-- ["{npc:14527}, a troll, stands in the west of {zone:1449}. Talk to her and she becomes {npc:14533}, with a pet of her own. Alone, without your pet."] = "{npc:14527}, eine Trollin, steht im Westen des {zone:1449}. Sprich mit ihr, und sie wird zu {npc:14533}, mit eigenem Begleiter. Allein, ohne deinen Begleiter.",
	-- ["{npc:14529}, a human, stands in the west of the {zone:1428}. Talk to him and he becomes {npc:14534}. Alone, without your pet."] = "{npc:14529}, ein Mensch, steht im Westen der {zone:1428}. Sprich mit ihm, und er wird zu {npc:14534}. Allein, ohne deinen Begleiter.",
	-- ["{npc:14531}, a tauren, waits in the north-east of {zone:1452}. Talk to him and he becomes {npc:14535}. Fight every demon alone and without your pet: help of any kind makes it vanish. Loot the head."] = "{npc:14531}, ein Tauren, wartet im Nordosten von {zone:1452}. Sprich mit ihm, und er wird zu {npc:14535}. Kämpfe gegen jeden Dämon allein und ohne Begleiter: Jede Art von Hilfe lässt ihn verschwinden. Plündere den Kopf.",
	-- ["{npc:14536}, a gnome, stands in the south-west of {zone:1451}. Talk to him and he becomes {npc:14530}. Alone, without your pet; keep away from the beetles he calls."] = "{npc:14536}, ein Gnom, steht im Südwesten von {zone:1451}. Sprich mit ihm, und er wird zu {npc:14530}. Allein, ohne deinen Begleiter; halte dich von den Käfern fern, die er ruft.",
